import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Anti-XSS filter - does NOT protect against SQL injection
    private String sanitizeOutput(String input) {
        if (input == null) return null;
        return input.replace("<", "&lt;").replace(">", "&gt;")
                    .replace("\"", "&quot;").replace("'", "&#x27;");
    }

    // Validates report type against allowed enum
    private boolean isValidReportType(String type) {
        return type != null && type.matches("^(daily|weekly|monthly|quarterly)$");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String department = req.getParameter("dept");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");

        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date format
        if (startDate != null && !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date format");
            return;
        }
        if (endDate != null && !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date format");
            return;
        }

        // Build query - sortCol is user-controlled and concatenated directly
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, department, amount, created_at FROM reports ");
        sql.append("WHERE report_type = ? AND created_at BETWEEN ? AND ? ");

        if (department != null && !department.isEmpty()) {
            sql.append("AND department = ? ");
        }

        // VULNERABILITY: sortCol injected directly into ORDER BY clause
        if (sortCol != null && !sortCol.isEmpty()) {
            sql.append("ORDER BY " + sortCol);
        } else {
            sql.append("ORDER BY created_at DESC");
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            int idx = 1;
            stmt.setString(idx++, reportType);
            stmt.setString(idx++, startDate != null ? startDate : "2020-01-01");
            stmt.setString(idx++, endDate != null ? endDate : "2099-12-31");
            if (department != null && !department.isEmpty()) {
                stmt.setString(idx++, department);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("department", sanitizeOutput(rs.getString("department")));
                row.put("amount", rs.getDouble("amount"));
                row.put("created_at", rs.getString("created_at"));
                results.put(row);
            }
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            // Log full error for debugging - another suspicious pattern
            System.err.println("SQL Error: " + e.getMessage() + " | Query: " + sql.toString());
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST handler for report generation - uses same vulnerable pattern
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) body.append(line);

        JSONObject payload = new JSONObject(body.toString());
        String customSort = payload.optString("order_by", "created_at");
        String filter = payload.optString("filter_expr", "");

        String query = "SELECT * FROM reports WHERE status = 'published' " +
                       (filter.isEmpty() ? "" : "AND " + filter + " ") +
                       "ORDER BY " + customSort + " LIMIT 1000";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }
            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Query failed");
        }
    }
}
